            "name": "CustomerManagement:cartItemManagement.js",
            "code": "window.BAKEIT_ENTITY_CONFIG = {\n    key: \"cart_items\",\n    dataset: \"CartItems.json\",\n    singular: \"Cart Item\",\n    idKey: \"cartItemId\",\n    startId: 40000,\n    secondaryStatKey: \"cartId\",\n    fields: [\n        { key: \"cartItemId\", name: \"CartItemID\", label: \"Cart Item ID\", type: \"number\", readonly: true },\n        { key: \"cartId\", name: \"CartID\", label: \"Cart ID\", type: \"number\" },\n        { key: \"productId\", name: \"ProductID\", label: \"Product ID\", type: \"number\" },\n        { key: \"quantity\", name: \"Quantity\", label: \"Quantity\", type: \"number\" }\n    ],\n    columns: [\n        { key: \"cartItemId\", label: \"Cart Item ID\" },\n        { key: \"cartId\", label: \"Cart ID\" },\n        { key: \"productId\", label: \"Product ID\" },\n        { key: \"quantity\", label: \"Quantity\" }\n    ]\n};\n"
