        {
            "name": "CustomerManagement:simpleEntityPage.js",
            "code": "(function() {\n    var config = window.BAKEIT_ENTITY_CONFIG;\n    if (!config) return;\n\n    var rows = [];\n    var filteredRows = [];\n    var currentPage = 1;\n    var pageSize = 8;\n    var storageKey = \"bakeit_admin_\" + config.key;\n\n    function escapeHtml(value) {\n        return String(value === null || value === undefined ? \"\" : value)\n            .replace(/&/g, \"&amp;\")\n            .replace(/</g, \"&lt;\")\n            .replace(/>/g, \"&gt;\")\n            .replace(/\"/g, \"&quot;\")\n            .replace(/'/g, \"&#039;\");\n    }\n\n    function normalize(row) {\n        var normalized = {};\n        config.fields.forEach(function(field) {\n            var value = row[field.name] !== undefined ? row[field.name] : row[field.key];\n            normalized[field.key] = field.type === \"number\" ? Number(value) || 0 : (value === undefined ? \"\" : value);\n        });\n        return normalized;\n    }\n\n    function sourceRow(row) {\n        var output = {};\n        config.fields.forEach(function(field) {\n            output[field.name] = row[field.key];\n        });\n        return output;\n    }\n\n    function saveRows() {\n        localStorage.setItem(storageKey, JSON.stringify(rows.map(sourceRow)));\n    }\n\n    function loadRowsFromStorage() {\n        try {\n            var saved = JSON.parse(localStorage.getItem(storageKey) || \"[]\");\n            return Array.isArray(saved) && saved.length ? saved.map(normalize) : null;\n        } catch (error) {\n            return null;\n        }\n    }\n\n    function nextId() {\n        var idField = config.fields[0];\n        return rows.reduce(function(maxId, row) {\n            return Math.max(maxId, Number(row[idField.key]) || 0);\n        }, config.startId || 0) + 1;\n    }\n\n    function statusClass(value) {\n        if ([\"Active\", \"Available\", \"Open\"].indexOf(value) >= 0) return \"in\";\n        if ([\"Inactive\", \"Expired\", \"PendingCustomer\", \"InReview\"].indexOf(value) >= 0) return \"low\";\n        return \"out\";\n    }\n\n    function renderStats() {\n        document.getElementById(\"totalRows\").textContent = rows.length;\n        var statusField = config.fields.find(function(field) { return field.status; });\n        var unique = new Set(rows.map(function(row) {\n            return row[config.secondaryStatKey || config.fields[1].key];\n        })).size;\n        document.getElementById(\"uniqueRows\").textContent = unique;\n\n        if (statusField) {\n            document.getElementById(\"activeRows\").textContent = rows.filter(function(row) {\n                return [\"Active\", \"Available\", \"Open\"].indexOf(row[statusField.key]) >= 0;\n            }).length;\n            document.getElementById(\"inactiveRows\").textContent = rows.filter(function(row) {\n                return [\"Active\", \"Available\", \"Open\"].indexOf(row[statusField.key]) < 0;\n            }).length;\n        } else {\n            document.getElementById(\"activeRows\").textContent = rows.length;\n            document.getElementById(\"inactiveRows\").textContent = 0;\n        }\n    }\n\n    function renderFilter() {\n        var filter = document.getElementById(\"entityStatusFilter\");\n        var statusField = config.fields.find(function(field) { return field.status; });\n        if (!filter || !statusField) return;\n        var selected = filter.value;\n        var statuses = Array.from(new Set(rows.map(function(row) {\n            return row[statusField.key];\n        }).filter(Boolean))).sort();\n        filter.innerHTML = '<option value=\"all\">All statuses</option>' + statuses.map(function(status) {\n            return '<option value=\"' + escapeHtml(status) + '\">' + escapeHtml(status) + '</option>';\n        }).join(\"\");\n        filter.value = statuses.indexOf(selected) >= 0 ? selected : \"all\";\n    }\n\n    function renderTable() {\n        var tbody = document.getElementById(\"entityTableBody\");\n        var start = (currentPage - 1) * pageSize;\n        var pageRows = filteredRows.slice(start, start + pageSize);\n\n        if (!pageRows.length) {\n            tbody.innerHTML = '<tr><td colspan=\"' + (config.columns.length + 2) + '\"><div class=\"empty-state\"><i class=\"fa-regular fa-folder-open\"></i><h3>No data found</h3><p>Try another keyword or status.</p></div></td></tr>';\n            renderPagination();\n            return;\n        }\n\n        tbody.innerHTML = pageRows.map(function(row) {\n            var cells = config.columns.map(function(column) {\n                var value = row[column.key];\n                if (column.status) return '<td><span class=\"product-status ' + statusClass(value) + '\">' + escapeHtml(value) + '</span></td>';\n                return '<td>' + escapeHtml(value) + '</td>';\n            }).join(\"\");\n            return '<tr><td><input type=\"checkbox\" aria-label=\"Select row\"></td>' + cells +\n                '<td><div class=\"row-actions\"><button type=\"button\" class=\"view-row-btn\" data-row-id=\"' + row[config.idKey] + '\" aria-label=\"View\"><i class=\"fa-solid fa-ellipsis-vertical\"></i></button><button type=\"button\" class=\"edit-row-btn\" data-row-id=\"' + row[config.idKey] + '\" aria-label=\"Edit\"><i class=\"fa-regular fa-pen-to-square\"></i></button></div></td></tr>';\n        }).join(\"\");\n        renderPagination();\n    }\n\n    function renderPagination() {\n        var totalPages = Math.max(1, Math.ceil(filteredRows.length / pageSize));\n        var start = filteredRows.length ? ((currentPage - 1) * pageSize) + 1 : 0;\n        var end = Math.min(currentPage * pageSize, filteredRows.length);\n        var buttons = [\n            '<button type=\"button\" data-page=\"prev\" aria-label=\"Previous page\"><i class=\"fa-solid fa-chevron-left\"></i></button>'\n        ];\n        for (var page = 1; page <= Math.min(totalPages, 5); page += 1) {\n            buttons.push('<button type=\"button\" data-page=\"' + page + '\" class=\"' + (page === currentPage ? \"active\" : \"\") + '\">' + page + '</button>');\n        }\n        buttons.push('<button type=\"button\" data-page=\"next\" aria-label=\"Next page\"><i class=\"fa-solid fa-chevron-right\"></i></button>');\n        document.getElementById(\"entityRangeText\").textContent = \"Showing \" + start + \" to \" + end + \" of \" + filteredRows.length + \" rows\";\n        document.getElementById(\"entityPaginationControls\").innerHTML = buttons.join(\"\");\n    }\n\n    function applyFilters() {\n        var keyword = document.getElementById(\"entitySearchInput\").value.trim().toLowerCase();\n        var globalKeyword = document.getElementById(\"globalEntitySearchInput\").value.trim().toLowerCase();\n        var statusFilter = document.getElementById(\"entityStatusFilter\");\n        var statusValue = statusFilter ? statusFilter.value : \"all\";\n        var statusField = config.fields.find(function(field) { return field.status; });\n        var query = keyword || globalKeyword;\n\n        filteredRows = rows.filter(function(row) {\n            var matchesStatus = !statusField || statusValue === \"all\" || row[statusField.key] === statusValue;\n            var matchesQuery = !query || config.fields.some(function(field) {\n                return String(row[field.key]).toLowerCase().includes(query);\n            });\n            return matchesStatus && matchesQuery;\n        });\n        currentPage = 1;\n        renderTable();\n    }\n\n    function rowById(id) {\n        return rows.find(function(row) {\n            return String(row[config.idKey]) === String(id);\n        });\n    }\n\n    function modalMarkup(title, body) {\n        return '<div class=\"product-modal-backdrop\" id=\"entityModalBackdrop\"><section class=\"product-modal\" role=\"dialog\" aria-modal=\"true\"><div class=\"product-modal-header\"><h2>' + escapeHtml(title) + '</h2><button type=\"button\" class=\"close-entity-modal\" aria-label=\"Close modal\"><i class=\"fa-solid fa-xmark\"></i></button></div>' + body + '</section></div>';\n    }\n\n    function closeModal() {\n        var modal = document.getElementById(\"entityModalBackdrop\");\n        if (modal) modal.remove();\n    }\n\n    function openModal(title, body) {\n        closeModal();\n        document.body.insertAdjacentHTML(\"beforeend\", modalMarkup(title, body));\n        document.querySelector(\".close-entity-modal\").addEventListener(\"click\", closeModal);\n        document.getElementById(\"entityModalBackdrop\").addEventListener(\"click\", function(event) {\n            if (event.target.id === \"entityModalBackdrop\") closeModal();\n        });\n    }\n\n    function fieldInput(field, value) {\n        if (field.select) {\n            return '<select name=\"' + field.key + '\">' + field.select.map(function(option) {\n                return '<option value=\"' + escapeHtml(option) + '\"' + (String(option) === String(value) ? \" selected\" : \"\") + '>' + escapeHtml(option) + '</option>';\n            }).join(\"\") + '</select>';\n        }\n        return '<input name=\"' + field.key + '\" type=\"' + (field.type === \"number\" ? \"number\" : field.type === \"date\" ? \"date\" : field.type === \"datetime\" ? \"datetime-local\" : \"text\") + '\" value=\"' + escapeHtml(value || \"\") + '\"' + (field.readonly ? \" readonly\" : \"\") + ' required>';\n    }\n\n    function formMarkup(row) {\n        var fields = config.fields.map(function(field) {\n            var value = row ? row[field.key] : (field.key === config.idKey ? nextId() : \"\");\n            if (field.type === \"datetime\" && value) value = String(value).slice(0, 16);\n            return '<div class=\"form-row\"><label>' + escapeHtml(field.label) + '</label>' + fieldInput(field, value) + '</div>';\n        }).join(\"\");\n        return '<form class=\"product-form\" id=\"entityForm\">' + fields + '<div class=\"product-form-actions\"><button type=\"button\" class=\"secondary-btn\" id=\"cancelEntityForm\">Cancel</button><button type=\"submit\" class=\"primary-btn\">Save</button></div></form>';\n    }\n\n    function editRow(id) {\n        var row = rowById(id);\n        openModal(row ? \"Edit \" + config.singular : \"Add \" + config.singular, formMarkup(row));\n        document.getElementById(\"cancelEntityForm\").addEventListener(\"click\", closeModal);\n        document.getElementById(\"entityForm\").addEventListener(\"submit\", function(event) {\n            event.preventDefault();\n            var data = new FormData(event.currentTarget);\n            var next = {};\n            config.fields.forEach(function(field) {\n                next[field.key] = field.type === \"number\" ? Number(data.get(field.key)) || 0 : data.get(field.key);\n            });\n            if (row) {\n                rows = rows.map(function(item) {\n                    return String(item[config.idKey]) === String(next[config.idKey]) ? next : item;\n                });\n            } else {\n                rows.unshift(next);\n            }\n            saveRows();\n            renderStats();\n            renderFilter();\n            applyFilters();\n            closeModal();\n        });\n    }\n\n    function viewRow(id) {\n        var row = rowById(id);\n        if (!row) return;\n        var body = '<div class=\"product-detail-grid\">' + config.fields.map(function(field) {\n            return '<span>' + escapeHtml(field.label) + '</span><strong>' + escapeHtml(row[field.key]) + '</strong>';\n        }).join(\"\") + '</div><div class=\"product-form-actions\"><button type=\"button\" class=\"secondary-btn\" id=\"closeEntityDetail\">Close</button><button type=\"button\" class=\"primary-btn\" id=\"editEntityFromDetail\">Edit</button></div>';\n        openModal(config.singular + \" Info\", body);\n        document.getElementById(\"closeEntityDetail\").addEventListener(\"click\", closeModal);\n        document.getElementById(\"editEntityFromDetail\").addEventListener(\"click\", function() { editRow(id); });\n    }\n\n    function exportRows() {\n        var csvRows = [config.fields.map(function(field) { return field.name; })];\n        filteredRows.forEach(function(row) {\n            csvRows.push(config.fields.map(function(field) { return row[field.key]; }));\n        });\n        var csv = csvRows.map(function(row) {\n            return row.map(function(cell) { return '\"' + String(cell === null || cell === undefined ? \"\" : cell).replace(/\"/g, '\"\"') + '\"'; }).join(\",\");\n        }).join(\"\\n\");\n        var blob = new Blob([\"\\ufeff\" + csv], { type: \"text/csv;charset=utf-8;\" });\n        var url = URL.createObjectURL(blob);\n        var link = document.createElement(\"a\");\n        link.href = url;\n        link.download = config.key + \".csv\";\n        document.body.appendChild(link);\n        link.click();\n        document.body.removeChild(link);\n        URL.revokeObjectURL(url);\n    }\n\n    function setupEvents() {\n        document.getElementById(\"entitySearchInput\").addEventListener(\"input\", applyFilters);\n        document.getElementById(\"globalEntitySearchInput\").addEventListener(\"input\", applyFilters);\n        var statusFilter = document.getElementById(\"entityStatusFilter\");\n        if (statusFilter) statusFilter.addEventListener(\"change\", applyFilters);\n        document.getElementById(\"addEntityBtn\").addEventListener(\"click\", function() { editRow(); });\n        document.getElementById(\"exportEntityBtn\").addEventListener(\"click\", exportRows);\n        document.getElementById(\"entityTableBody\").addEventListener(\"click\", function(event) {\n            var viewButton = event.target.closest(\".view-row-btn\");\n            var editButton = event.target.closest(\".edit-row-btn\");\n            if (viewButton) viewRow(viewButton.dataset.rowId);\n            if (editButton) editRow(editButton.dataset.rowId);\n        });\n        document.getElementById(\"entityPaginationControls\").addEventListener(\"click\", function(event) {\n            var button = event.target.closest(\"button\");\n            if (!button) return;\n            var totalPages = Math.max(1, Math.ceil(filteredRows.length / pageSize));\n            if (button.dataset.page === \"prev\") currentPage = Math.max(1, currentPage - 1);\n            else if (button.dataset.page === \"next\") currentPage = Math.min(totalPages, currentPage + 1);\n            else currentPage = Number(button.dataset.page);\n            renderTable();\n        });\n    }\n\n    async function init() {\n        var tableBody = document.getElementById(\"entityTableBody\");\n        if (!tableBody) return;\n        try {\n            var response = await fetch(\"../../../datasets/\" + config.dataset);\n            var data = await response.json();\n            rows = loadRowsFromStorage() || data.map(normalize);\n            filteredRows = rows.slice();\n            renderStats();\n            renderFilter();\n            setupEvents();\n            applyFilters();\n        } catch (error) {\n            tableBody.innerHTML = '<tr><td colspan=\"' + (config.columns.length + 2) + '\"><div class=\"empty-state\"><i class=\"fa-solid fa-triangle-exclamation\"></i><h3>Cannot load data</h3><p>Please check datasets/' + escapeHtml(config.dataset) + '.</p></div></td></tr>';\n        }\n    }\n\n    document.addEventListener(\"DOMContentLoaded\", init);\n})();\n"
        }
