        {
            "name": "CustomerManagement:customerManagement.js",
            "code": "(function() {\n    var customers = [];\n    var filteredCustomers = [];\n    var currentPage = 1;\n    var pageSize = 8;\n    var storageKey = \"bakeit_admin_customers\";\n\n    function escapeHtml(value) {\n        return String(value || \"\")\n            .replace(/&/g, \"&amp;\")\n            .replace(/</g, \"&lt;\")\n            .replace(/>/g, \"&gt;\")\n            .replace(/\"/g, \"&quot;\")\n            .replace(/'/g, \"&#039;\");\n    }\n\n    function formatDate(value) {\n        if (!value) return \"N/A\";\n        var date = new Date(value);\n        if (Number.isNaN(date.getTime())) return \"N/A\";\n        return new Intl.DateTimeFormat(\"en-GB\", {\n            day: \"2-digit\",\n            month: \"short\",\n            year: \"numeric\"\n        }).format(date);\n    }\n\n    function csvValue(value) {\n        var text = String(value === undefined || value === null ? \"\" : value);\n        return '\"' + text.replace(/\"/g, '\"\"') + '\"';\n    }\n\n    function downloadCsv(filename, headers, rows) {\n        var csv = [headers.map(csvValue).join(\",\")].concat(rows.map(function(row) {\n            return row.map(csvValue).join(\",\");\n        })).join(\"\\n\");\n        var blob = new Blob([\"\\ufeff\" + csv], { type: \"text/csv;charset=utf-8;\" });\n        var link = document.createElement(\"a\");\n        var url = URL.createObjectURL(blob);\n        link.href = url;\n        link.download = filename;\n        document.body.appendChild(link);\n        link.click();\n        link.remove();\n        setTimeout(function() {\n            URL.revokeObjectURL(url);\n        }, 1000);\n    }\n\n    function normalizeStatus(status) {\n        return status === \"Blocked\" ? \"Blocked\" : \"Active\";\n    }\n\n    function normalizeCustomer(customer) {\n        return {\n            id: Number(customer.CustomerID || customer.id) || generateNextId(),\n            fullName: customer.FullName || customer.fullName || \"\",\n            email: customer.Email || customer.email || \"\",\n            phone: customer.Phone || customer.phone || \"\",\n            createdAt: customer.CreatedAt || customer.createdAt || new Date().toISOString(),\n            loyaltyPoint: Number(customer.LoyaltyPoint || customer.loyaltyPoint) || 0,\n            status: normalizeStatus(customer.CustomerStatus || customer.status),\n            supportRequests: Array.isArray(customer.SupportRequests || customer.supportRequests)\n                ? (customer.SupportRequests || customer.supportRequests)\n                : []\n        };\n    }\n\n    function saveCustomersToStorage() {\n        localStorage.setItem(storageKey, JSON.stringify(customers));\n    }\n\n    function loadCustomersFromStorage() {\n        try {\n            var saved = JSON.parse(localStorage.getItem(storageKey) || \"[]\");\n            return Array.isArray(saved) && saved.length ? saved.map(normalizeCustomer) : null;\n        } catch (error) {\n            return null;\n        }\n    }\n\n    function generateNextId() {\n        return customers.reduce(function(maxId, customer) {\n            return Math.max(maxId, Number(customer.id) || 0);\n        }, 1000) + 1;\n    }\n\n    function unresolvedRequests(customer) {\n        return customer.supportRequests.filter(function(request) {\n            return request.RequestStatus !== \"Resolved\" && !request.ResolvedAt;\n        }).length;\n    }\n\n    function customerInitials(customer) {\n        var parts = customer.fullName.trim().split(/\\s+/).filter(Boolean);\n        if (!parts.length) return \"C\";\n        if (parts.length === 1) return parts[0].charAt(0).toUpperCase();\n        return (parts[0].charAt(0) + parts[parts.length - 1].charAt(0)).toUpperCase();\n    }\n\n    function statusClass(status) {\n        return status === \"Blocked\" ? \"out\" : \"in\";\n    }\n\n    function requestBadge(customer) {\n        var openCount = unresolvedRequests(customer);\n        if (!openCount) return '<span class=\"product-status in\">0 open</span>';\n        return '<span class=\"product-status low\">' + openCount + ' open</span>';\n    }\n\n    function renderStats() {\n        var active = customers.filter(function(customer) { return customer.status === \"Active\"; }).length;\n        var blocked = customers.filter(function(customer) { return customer.status === \"Blocked\"; }).length;\n        var open = customers.reduce(function(total, customer) {\n            return total + unresolvedRequests(customer);\n        }, 0);\n\n        document.getElementById(\"totalCustomers\").textContent = customers.length;\n        document.getElementById(\"activeCustomers\").textContent = active;\n        document.getElementById(\"blockedCustomers\").textContent = blocked;\n        document.getElementById(\"openRequests\").textContent = open;\n    }\n\n    function renderStatusFilter() {\n        var filter = document.getElementById(\"customerStatusFilter\");\n        var statuses = Array.from(new Set(customers.map(function(customer) {\n            return customer.status;\n        }))).sort();\n\n        filter.innerHTML = '<option value=\"all\">All statuses</option>' + statuses.map(function(status) {\n            return '<option value=\"' + escapeHtml(status) + '\">' + escapeHtml(status) + '</option>';\n        }).join(\"\");\n    }\n\n    function renderTable() {\n        var tbody = document.getElementById(\"customerTableBody\");\n        var start = (currentPage - 1) * pageSize;\n        var pageCustomers = filteredCustomers.slice(start, start + pageSize);\n\n        if (!pageCustomers.length) {\n            tbody.innerHTML = '<tr><td colspan=\"7\"><div class=\"empty-state\"><i class=\"fa-regular fa-folder-open\"></i><h3>No customers found</h3><p>Try another keyword or status.</p></div></td></tr>';\n            renderPagination();\n            return;\n        }\n\n        tbody.innerHTML = pageCustomers.map(function(customer) {\n            return [\n                '<tr>',\n                '<td><input type=\"checkbox\" aria-label=\"Select ' + escapeHtml(customer.fullName) + '\"></td>',\n                '<td>',\n                '<div class=\"product-cell\">',\n                '<div class=\"product-thumb\"><span style=\"display:grid;\">' + escapeHtml(customerInitials(customer)) + '</span></div>',\n                '<div><h4>' + escapeHtml(customer.fullName) + '</h4><p>' + escapeHtml(customer.email) + '</p></div>',\n                '</div>',\n                '</td>',\n                '<td>' + escapeHtml(customer.phone) + '</td>',\n                '<td>' + escapeHtml(formatDate(customer.createdAt)) + '</td>',\n                '<td><span class=\"product-status ' + statusClass(customer.status) + '\">' + escapeHtml(customer.status) + '</span></td>',\n                '<td>' + requestBadge(customer) + '</td>',\n                '<td><div class=\"row-actions\"><button type=\"button\" class=\"edit-customer-btn\" data-customer-id=\"' + customer.id + '\" aria-label=\"Edit customer\"><i class=\"fa-regular fa-pen-to-square\"></i></button><button type=\"button\" class=\"view-customer-btn\" data-customer-id=\"' + customer.id + '\" aria-label=\"View customer info\"><i class=\"fa-solid fa-ellipsis-vertical\"></i></button></div></td>',\n                '</tr>'\n            ].join(\"\");\n        }).join(\"\");\n\n        renderPagination();\n    }\n\n    function renderPagination() {\n        var totalPages = Math.max(1, Math.ceil(filteredCustomers.length / pageSize));\n        var start = filteredCustomers.length ? ((currentPage - 1) * pageSize) + 1 : 0;\n        var end = Math.min(currentPage * pageSize, filteredCustomers.length);\n        var rangeText = document.getElementById(\"customerRangeText\");\n        var controls = document.getElementById(\"customerPaginationControls\");\n\n        rangeText.textContent = \"Showing \" + start + \" to \" + end + \" of \" + filteredCustomers.length + \" customers\";\n\n        var maxVisiblePages = 5;\n        var firstVisiblePage = Math.max(1, currentPage - Math.floor(maxVisiblePages / 2));\n        var lastVisiblePage = Math.min(totalPages, firstVisiblePage + maxVisiblePages - 1);\n\n        if (lastVisiblePage - firstVisiblePage + 1 < maxVisiblePages) {\n            firstVisiblePage = Math.max(1, lastVisiblePage - maxVisiblePages + 1);\n        }\n\n        var buttons = [\n            '<button type=\"button\" data-page=\"first\" aria-label=\"First page\"><i class=\"fa-solid fa-angles-left\"></i></button>',\n            '<button type=\"button\" data-page=\"prev\" aria-label=\"Previous page\"><i class=\"fa-solid fa-chevron-left\"></i></button>'\n        ];\n\n        for (var page = firstVisiblePage; page <= lastVisiblePage; page += 1) {\n            buttons.push('<button type=\"button\" data-page=\"' + page + '\" class=\"' + (page === currentPage ? \"active\" : \"\") + '\">' + page + '</button>');\n        }\n\n        buttons.push('<button type=\"button\" data-page=\"next\" aria-label=\"Next page\"><i class=\"fa-solid fa-chevron-right\"></i></button>');\n        buttons.push('<button type=\"button\" data-page=\"last\" aria-label=\"Last page\"><i class=\"fa-solid fa-angles-right\"></i></button>');\n        controls.innerHTML = buttons.join(\"\");\n    }\n\n    function applyFilters() {\n        var keyword = document.getElementById(\"customerSearchInput\").value.trim().toLowerCase();\n        var globalKeyword = document.getElementById(\"globalCustomerSearchInput\").value.trim().toLowerCase();\n        var status = document.getElementById(\"customerStatusFilter\").value;\n        var query = keyword || globalKeyword;\n\n        filteredCustomers = customers.filter(function(customer) {\n            var matchesStatus = status === \"all\" || customer.status === status;\n            var matchesQuery = !query ||\n                customer.fullName.toLowerCase().includes(query) ||\n                customer.email.toLowerCase().includes(query) ||\n                customer.phone.toLowerCase().includes(query) ||\n                String(customer.id).includes(query);\n            return matchesStatus && matchesQuery;\n        });\n\n        currentPage = 1;\n        renderTable();\n    }\n\n    function customerById(customerId) {\n        return customers.find(function(customer) {\n            return String(customer.id) === String(customerId);\n        });\n    }\n\n    function exportCustomers() {\n        downloadCsv(\"bakeit-customers.csv\", [\n            \"Customer ID\",\n            \"Full Name\",\n            \"Email\",\n            \"Phone\",\n            \"Created At\",\n            \"Loyalty Point\",\n            \"Status\",\n            \"Open Requests\",\n            \"Total Requests\"\n        ], filteredCustomers.map(function(customer) {\n            return [\n                customer.id,\n                customer.fullName,\n                customer.email,\n                customer.phone,\n                customer.createdAt,\n                customer.loyaltyPoint,\n                customer.status,\n                unresolvedRequests(customer),\n                customer.supportRequests.length\n            ];\n        }));\n    }\n\n    function statusOptions(selectedStatus) {\n        return [\"Active\", \"Blocked\"].map(function(status) {\n            return '<option value=\"' + status + '\"' + (status === selectedStatus ? \" selected\" : \"\") + '>' + status + '</option>';\n        }).join(\"\");\n    }\n\n    function modalMarkup(title, body) {\n        return [\n            '<div class=\"product-modal-backdrop\" id=\"customerModalBackdrop\">',\n            '<section class=\"product-modal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"customerModalTitle\">',\n            '<div class=\"product-modal-header\">',\n            '<h2 id=\"customerModalTitle\">' + escapeHtml(title) + '</h2>',\n            '<button type=\"button\" class=\"close-product-modal\" aria-label=\"Close modal\"><i class=\"fa-solid fa-xmark\"></i></button>',\n            '</div>',\n            body,\n            '</section>',\n            '</div>'\n        ].join(\"\");\n    }\n\n    function closeCustomerModal() {\n        var modal = document.getElementById(\"customerModalBackdrop\");\n        if (modal) modal.remove();\n    }\n\n    function openCustomerModal(title, body) {\n        closeCustomerModal();\n        document.body.insertAdjacentHTML(\"beforeend\", modalMarkup(title, body));\n\n        document.getElementById(\"customerModalBackdrop\").addEventListener(\"click\", function(event) {\n            if (event.target.id === \"customerModalBackdrop\") closeCustomerModal();\n        });\n        document.querySelector(\".close-product-modal\").addEventListener(\"click\", closeCustomerModal);\n    }\n\n    function customerFormMarkup(mode, customer) {\n        return [\n            '<form class=\"product-form\" id=\"customerForm\" data-mode=\"' + mode + '\" data-customer-id=\"' + (customer ? customer.id : \"\") + '\">',\n            '<div class=\"form-row\"><label for=\"customerFullName\">Full name</label><input id=\"customerFullName\" name=\"fullName\" type=\"text\" value=\"' + escapeHtml(customer ? customer.fullName : \"\") + '\" required></div>',\n            '<div class=\"two-columns\">',\n            '<div class=\"form-row\"><label for=\"customerEmail\">Email</label><input id=\"customerEmail\" name=\"email\" type=\"email\" value=\"' + escapeHtml(customer ? customer.email : \"\") + '\" required></div>',\n            '<div class=\"form-row\"><label for=\"customerPhone\">Phone</label><input id=\"customerPhone\" name=\"phone\" type=\"tel\" value=\"' + escapeHtml(customer ? customer.phone : \"\") + '\" required></div>',\n            '</div>',\n            '<div class=\"two-columns\">',\n            '<div class=\"form-row\"><label for=\"customerStatus\">Status</label><select id=\"customerStatus\" name=\"status\">' + statusOptions(customer ? customer.status : \"Active\") + '</select></div>',\n            '<div class=\"form-row\"><label for=\"customerCreatedAt\">Created at</label><input id=\"customerCreatedAt\" name=\"createdAt\" type=\"datetime-local\" value=\"' + escapeHtml(customer ? customer.createdAt.slice(0, 16) : new Date().toISOString().slice(0, 16)) + '\" required></div>',\n            '</div>',\n            '<div class=\"product-form-actions\">',\n            '<button type=\"button\" class=\"secondary-btn\" id=\"cancelCustomerForm\">Cancel</button>',\n            '<button type=\"submit\" class=\"primary-btn\">' + (mode === \"add\" ? \"Add Customer\" : \"Save Changes\") + '</button>',\n            '</div>',\n            '</form>'\n        ].join(\"\");\n    }\n\n    function formCustomerData(form) {\n        var existingCustomer = customerById(form.dataset.customerId);\n        return {\n            id: form.dataset.mode === \"add\" ? generateNextId() : Number(form.dataset.customerId),\n            fullName: form.elements.fullName.value.trim(),\n            email: form.elements.email.value.trim(),\n            phone: form.elements.phone.value.trim(),\n            createdAt: form.elements.createdAt.value,\n            loyaltyPoint: existingCustomer ? existingCustomer.loyaltyPoint : 0,\n            status: normalizeStatus(form.elements.status.value),\n            supportRequests: existingCustomer ? existingCustomer.supportRequests : []\n        };\n    }\n\n    function refreshCustomersAfterChange() {\n        saveCustomersToStorage();\n        renderStats();\n        renderStatusFilter();\n        applyFilters();\n    }\n\n    function addCustomer() {\n        openCustomerModal(\"Add Customer\", customerFormMarkup(\"add\"));\n        document.getElementById(\"cancelCustomerForm\").addEventListener(\"click\", closeCustomerModal);\n        document.getElementById(\"customerForm\").addEventListener(\"submit\", function(event) {\n            event.preventDefault();\n            customers.unshift(formCustomerData(event.currentTarget));\n            closeCustomerModal();\n            refreshCustomersAfterChange();\n        });\n    }\n\n    function editCustomerInfo(customerId) {\n        var customer = customerById(customerId);\n        if (!customer) return;\n\n        openCustomerModal(\"Edit Customer Info\", customerFormMarkup(\"edit\", customer));\n        document.getElementById(\"cancelCustomerForm\").addEventListener(\"click\", closeCustomerModal);\n        document.getElementById(\"customerForm\").addEventListener(\"submit\", function(event) {\n            event.preventDefault();\n            var updatedCustomer = formCustomerData(event.currentTarget);\n            customers = customers.map(function(item) {\n                return String(item.id) === String(updatedCustomer.id) ? updatedCustomer : item;\n            });\n            closeCustomerModal();\n            refreshCustomersAfterChange();\n        });\n    }\n\n    function supportRequestMarkup(customer) {\n        if (!customer.supportRequests.length) {\n            return '<div class=\"category-detail-list\"><div><strong>No support requests</strong><p>This customer has no recorded support history.</p></div></div>';\n        }\n\n        return '<div class=\"category-detail-list\">' + customer.supportRequests.slice(0, 6).map(function(request) {\n            return [\n                '<div>',\n                '<strong>#' + escapeHtml(request.RequestID) + ' - ' + escapeHtml(request.RequestType) + '</strong>',\n                '<p>Order #' + escapeHtml(request.OrderID) + ' · ' + escapeHtml(request.RequestStatus) + ' · ' + escapeHtml(formatDate(request.CreatedAt)) + '</p>',\n                '<p>' + escapeHtml(request.RequestContent) + '</p>',\n                '</div>'\n            ].join(\"\");\n        }).join(\"\") + '</div>';\n    }\n\n    function viewCustomerInfo(customerId) {\n        var customer = customerById(customerId);\n        if (!customer) return;\n\n        openCustomerModal(\"Customer Info\", [\n            '<div class=\"product-detail-grid\">',\n            '<span>Customer ID</span><strong>#' + escapeHtml(customer.id) + '</strong>',\n            '<span>Name</span><strong>' + escapeHtml(customer.fullName) + '</strong>',\n            '<span>Email</span><strong>' + escapeHtml(customer.email) + '</strong>',\n            '<span>Phone</span><strong>' + escapeHtml(customer.phone) + '</strong>',\n            '<span>Joined</span><strong>' + escapeHtml(formatDate(customer.createdAt)) + '</strong>',\n            '<span>Status</span><strong>' + escapeHtml(customer.status) + '</strong>',\n            '<span>Requests</span><strong>' + unresolvedRequests(customer) + ' open / ' + customer.supportRequests.length + ' total</strong>',\n            '</div>',\n            supportRequestMarkup(customer),\n            '<div class=\"product-form-actions\">',\n            '<button type=\"button\" class=\"secondary-btn\" id=\"closeCustomerDetail\">Close</button>',\n            '<button type=\"button\" class=\"primary-btn\" id=\"editCustomerFromDetail\">Edit Customer</button>',\n            '</div>'\n        ].join(\"\"));\n\n        document.getElementById(\"closeCustomerDetail\").addEventListener(\"click\", closeCustomerModal);\n        document.getElementById(\"editCustomerFromDetail\").addEventListener(\"click\", function() {\n            editCustomerInfo(customer.id);\n        });\n    }\n\n    function setupEvents() {\n        document.getElementById(\"customerSearchInput\").addEventListener(\"input\", applyFilters);\n        document.getElementById(\"globalCustomerSearchInput\").addEventListener(\"input\", applyFilters);\n        document.getElementById(\"customerStatusFilter\").addEventListener(\"change\", applyFilters);\n        document.getElementById(\"applyCustomerFilterBtn\").addEventListener(\"click\", applyFilters);\n        document.getElementById(\"exportCustomersBtn\").addEventListener(\"click\", exportCustomers);\n        document.querySelector(\".add-customer-btn\").addEventListener(\"click\", addCustomer);\n        document.getElementById(\"customerTableBody\").addEventListener(\"click\", function(event) {\n            var editButton = event.target.closest(\".edit-customer-btn\");\n            var viewButton = event.target.closest(\".view-customer-btn\");\n\n            if (editButton) editCustomerInfo(editButton.dataset.customerId);\n            if (viewButton) viewCustomerInfo(viewButton.dataset.customerId);\n        });\n        document.getElementById(\"customerPaginationControls\").addEventListener(\"click\", function(event) {\n            var button = event.target.closest(\"button\");\n            if (!button) return;\n\n            var totalPages = Math.max(1, Math.ceil(filteredCustomers.length / pageSize));\n            var page = button.dataset.page;\n\n            if (page === \"first\") currentPage = 1;\n            else if (page === \"prev\") currentPage = Math.max(1, currentPage - 1);\n            else if (page === \"next\") currentPage = Math.min(totalPages, currentPage + 1);\n            else if (page === \"last\") currentPage = totalPages;\n            else currentPage = Number(page);\n\n            renderTable();\n        });\n    }\n\n    async function initCustomerManagement() {\n        var tableBody = document.getElementById(\"customerTableBody\");\n        if (!tableBody) return;\n\n        try {\n            var response = await fetch(\"../../../datasets/Customers.json\");\n            var data = await response.json();\n            customers = loadCustomersFromStorage() || data.map(normalizeCustomer);\n            filteredCustomers = customers.slice();\n\n            renderStats();\n            renderStatusFilter();\n            setupEvents();\n            renderTable();\n        } catch (error) {\n            tableBody.innerHTML = '<tr><td colspan=\"7\"><div class=\"empty-state\"><i class=\"fa-solid fa-triangle-exclamation\"></i><h3>Cannot load customers</h3><p>Please check datasets/Customers.json.</p></div></td></tr>';\n        }\n    }\n\n    document.addEventListener(\"DOMContentLoaded\", initCustomerManagement);\n})();\n"
        }
